'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Tabs, TabList, Tab, TabPanel } from '@mui/joy';
import InventoryView from '@/app/components/Compare/InventoryView';
import PrepProcessView from '@/app/components/Compare/PrepProcessView';
import PerformanceView from '@/app/components/Compare/PerformanceView';
import { fetchAllRestaurants, fetchRestaurantDetails, Restaurant, RestaurantDetails } from '@/app/actions/restaurantActions';

export default function RestaurantViewPage() {
  const [selectedRestaurant, setSelectedRestaurant] = useState<number | null>(null);
  
  // Fetch all restaurants the user has access to
  const { data: restaurants = [], isLoading: isLoadingRestaurants } = useQuery<Restaurant[]>({
    queryKey: ['restaurants'],
    queryFn: fetchAllRestaurants,
  });
  
  // Fetch details for the selected restaurant
  const { data: restaurantDetails, isLoading: isLoadingDetails } = useQuery<RestaurantDetails>({
    queryKey: ['restaurantDetails', selectedRestaurant],
    queryFn: () => fetchRestaurantDetails(selectedRestaurant!),
    enabled: !!selectedRestaurant,
  });

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Restaurant Dashboard</h1>
      
      {/* Restaurant Selection */}
      <div className="mb-6">
        <h2 className="text-lg font-semibold mb-2">Select a Restaurant</h2>
        {isLoadingRestaurants ? (
          <div>Loading restaurants...</div>
        ) : (
          <div className="flex gap-2 flex-wrap">
            {restaurants.map((restaurant: Restaurant) => (
              <button
                key={restaurant.restaurantId}
                onClick={() => setSelectedRestaurant(restaurant.restaurantId)}
                className={`px-4 py-2 rounded ${
                  selectedRestaurant === restaurant.restaurantId
                    ? 'bg-blue-500 text-white'
                    : 'bg-gray-200'
                }`}
              >
                {restaurant.restaurantName}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Selected Restaurant Info */}
      {selectedRestaurant && (
        <div className="mb-6">
          {isLoadingDetails ? (
            <div className="p-4 bg-blue-50 rounded-lg">Loading restaurant details...</div>
          ) : restaurantDetails ? (
            <div className="p-4 bg-blue-50 rounded-lg">
              <h2 className="text-lg font-semibold mb-2">
                {restaurantDetails.restaurant.restaurantName}
              </h2>
              
              {/* Restaurant Metrics */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-4">
                <div className="bg-white p-3 rounded shadow">
                  <h3 className="text-sm font-medium text-gray-500">Total Inventory Items</h3>
                  <p className="text-2xl font-bold">{restaurantDetails.metrics.inventory.totalItems}</p>
                </div>
                
                <div className="bg-white p-3 rounded shadow">
                  <h3 className="text-sm font-medium text-gray-500">Out of Stock</h3>
                  <p className="text-2xl font-bold text-red-600">{restaurantDetails.metrics.inventory.outOfStock}</p>
                </div>
                
                <div className="bg-white p-3 rounded shadow">
                  <h3 className="text-sm font-medium text-gray-500">Low Stock</h3>
                  <p className="text-2xl font-bold text-yellow-600">{restaurantDetails.metrics.inventory.lowStock}</p>
                </div>
              </div>
            </div>
          ) : (
            <div className="p-4 bg-red-50 rounded-lg text-red-700">
              Failed to load restaurant details
            </div>
          )}
        </div>
      )}

      {/* View Tabs */}
      <Tabs defaultValue="inventory">
        <TabList>
          <Tab value="inventory">Inventory</Tab>
          <Tab value="prep">Preparation Processes</Tab>
          <Tab value="performance">Performance Metrics</Tab>
        </TabList>
        
        <TabPanel value="inventory">
          <InventoryView restaurantId={selectedRestaurant} />
        </TabPanel>
        
        <TabPanel value="prep">
          <PrepProcessView restaurantId={selectedRestaurant} />
        </TabPanel>
        
        <TabPanel value="performance">
          <PerformanceView restaurantId={selectedRestaurant} />
        </TabPanel>
      </Tabs>
    </div>
  );
} 